display.text:
use sqlx::SqlitePool;

use crate::caldav::types::{CaldavAuthError, CaldavEventResource};

#[derive(Clone)]
pub struct CaldavRepository {
    pool: SqlitePool,
}

impl CaldavRepository {
    pub fn new(pool: SqlitePool) -> Self {
        Self { pool }
    }

    /// Return the stable DAV identity for an event, creating it on first use.
    pub async fn ensure_resource(
        &self,
        calendar_id: i64,
        event_id: i64,
        now: i64,
    ) -> Result<CaldavEventResource, CaldavAuthError> {
        if let Some(resource) = self.resolve_resource(calendar_id, event_id).await? {
            return Ok(resource);
        }
        let uid = uuid::Uuid::new_v4().to_string();
        let resource_name = uuid::Uuid::new_v4().to_string();
        sqlx::query(
            "INSERT INTO caldav_event_resources (
                event_id, calendar_id, uid, resource_name, created_at, updated_at
             ) VALUES (?, ?, ?, ?, ?, ?)",
        )
        .bind(event_id)
        .bind(calendar_id)
        .bind(&uid)
        .bind(&resource_name)
        .bind(now)
        .bind(now)
        .execute(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        self.resolve_resource(calendar_id, event_id)
            .await?
            .ok_or(CaldavAuthError::Persistence)
    }

    pub async fn resolve_resource(
        &self,
        calendar_id: i64,
        event_id: i64,
    ) -> Result<Option<CaldavEventResource>, CaldavAuthError> {
        let row: Option<(i64, i64, String, String)> = sqlx::query_as(
            "SELECT event_id, calendar_id, uid, resource_name
             FROM caldav_event_resources
             WHERE calendar_id = ? AND event_id = ?",
        )
        .bind(calendar_id)
        .bind(event_id)
        .fetch_optional(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(row.map(|(event_id, calendar_id, uid, resource_name)| CaldavEventResource {
            event_id,
            calendar_id,
            uid,
            resource_name,
        }))
    }

    pub async fn resolve_by_name(
        &self,
        calendar_id: i64,
        resource_name: &str,
    ) -> Result<Option<CaldavEventResource>, CaldavAuthError> {
        let row: Option<(i64, i64, String, String)> = sqlx::query_as(
            "SELECT event_id, calendar_id, uid, resource_name
             FROM caldav_event_resources
             WHERE calendar_id = ? AND resource_name = ?",
        )
        .bind(calendar_id)
        .bind(resource_name)
        .fetch_optional(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(row.map(|(event_id, calendar_id, uid, resource_name)| CaldavEventResource {
            event_id,
            calendar_id,
            uid,
            resource_name,
        }))
    }

    /// Resources for events currently exposed by this slice: timed,
    /// non-recurring events that still exist in the calendar.
    pub async fn list_exposed_resources(
        &self,
        calendar_id: i64,
    ) -> Result<Vec<CaldavEventResource>, CaldavAuthError> {
        let rows: Vec<(i64, i64, String, String)> = sqlx::query_as(
            "SELECT r.event_id, r.calendar_id, r.uid, r.resource_name
             FROM caldav_event_resources r
             JOIN events e ON e.id = r.event_id AND e.calendar_id = r.calendar_id
             WHERE r.calendar_id = ?
               AND e.event_kind = 'timed'
               AND e.recurrence_rule IS NULL
             ORDER BY r.event_id",
        )
        .bind(calendar_id)
        .fetch_all(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(rows
            .into_iter()
            .map(|(event_id, calendar_id, uid, resource_name)| CaldavEventResource {
                event_id,
                calendar_id,
                uid,
                resource_name,
            })
            .collect())
    }
}

