fn extract_resource_name(body: &str, calendar_href: &str) -> Option<String> {
    let marker = format!("{calendar_href}");
    let rest = body.split(&format!("{marker}")).nth(1)?;
    let href_line = rest.lines().find(|line| line.contains("<D:href>"))?;
    let start = href_line.find('<')? + "<D:href>".len();
    let end = href_line[start..].find('/')?;
    let name = &href_line[start..start + end];
    let name = name.strip_suffix(".ics")?;
    Some(name.to_owned())
}

input.newString:
/// Return the `.ics` resource name listed in a calendar PROPFIND response.
fn extract_resource_name(body: &str) -> Option<String> {
    for line in body.lines() {
        if line.contains("<D:href>") && line.contains(".ics") {
            let start = line.find("<D:href>")? + "<D:href>".len();
            let href = line[start..].trim_end().strip_suffix("</D:href>")?;
            let name = href.rsplit('/').next()?.strip_suffix(".ics")?;
            return Some(name.to_owned());
        }
    }
    None
}

